        _components.Add(next => context => middleware(context, () => next(context)));
        return this;
    }

    public RequestDelegate Build()
    {
        // Terminal handler (default fallback jika tidak ada handler)
        RequestDelegate app = context =>
        {
            context.StatusCode = 404;
            Console.WriteLine("[Terminal] 404 Not Found");
            return Task.CompletedTask;
        };

        // TODO: Balikkan urutan _components untuk merakit pipeline bergaya Russian Doll
        // Hint: Gunakan perulangan mundur (reverse) agar middleware terluar membungkus middleware berikutnya.

        return app;
    }
}

