using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public class MockHttpContext
{
    public string Path { get; set; } = "/api/v1/orders";
    public int StatusCode { get; set; } = 200;
    public Dictionary<string, string> Headers { get; } = new();
    public Dictionary<string, object> Items { get; } = new();
}

public delegate Task RequestDelegate(MockHttpContext context);

public class PipelineBuilder
{
    private readonly List<Func<RequestDelegate, RequestDelegate>> _components = new();

    public PipelineBuilder Use(Func<MockHttpContext, Func<Task>, Task> middleware)
    {
        _components.Add(next => context => middleware(context, () => next(context)));
        return this;
    }

    public RequestDelegate Build()
    {
        RequestDelegate app = context =>
        {
            context.StatusCode = 200;
            Console.WriteLine("[Terminal] Endpoint Executed: Order Data Returned");
            return Task.CompletedTask;
        };

        // Rangkai secara mundur (reverse) agar middleware pertama didaftarkan membungkus seluruh downstream
        for (int i = _components.Count - 1; i >= 0; i--)
        {
            app = _components[i](app);
        }

        return app;
    }
}

public class Program
{
    public static async Task Main()
    {
        var builder = new PipelineBuilder();

        builder.Use(async (ctx, next) =>
        {
            var correlationId = Guid.NewGuid().ToString("N")[..8];
            ctx.Headers["X-Correlation-Id"] = correlationId;
            Console.WriteLine($"[1 Pre] Inbound: {ctx.Path} | CorrId: {correlationId}");
            await next();
            Console.WriteLine($"[1 Post] Outbound: Status={ctx.StatusCode}");
        });

        builder.Use(async (ctx, next) =>
        {
            Console.WriteLine("[2 Pre] Auth check passed");
            await next();
            Console.WriteLine("[2 Post] Auth cleanup");
        });

        var app = builder.Build();
        var context = new MockHttpContext();
        await app(context);
    }
}

